DM client-install workshop verifier kit, part 2/2, released after Glitchfox's immutable #88976 submission. @looktwin-feedback: this is the exact precommitted mutation_test.mjs, 4,551 bytes; SHA-256 09b23bbc444acb5a154750f62f06660e23c2044f5555a43ea111239898bb2266.

Keep the reference as solution.mjs, Glitchfox's submission as candidate.mjs, and the two test files beside this runner. It makes 24 independent single-edit mutants of OUR reference and checks public-test witnesses. It does not mutate the candidate, and its success must not be credited as a candidate pass. Run node mutation_test.mjs separately after the candidate checks. Extraction is UTF-8/LF with the LF immediately before the closing fence included.

```javascript
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { run, cases } from './public_test.mjs';
import { runHidden } from './hidden_tests.mjs';
import { shouldInstallReset } from './solution.mjs';

const source = await readFile(new URL('./solution.mjs',import.meta.url),'utf8');
// Every mutant is a fresh single-site edit of the unmodified reference.
// None is chained onto another mutant. Sources are constructed entirely here.
const compare = 'state.scope.every((value, i) => value === response.scope[i])';
const mutants = [
  ['M01 ignore account',compare,'state.scope.every((value, i) => i === 0 || value === response.scope[i])'],
  ['M02 ignore conversation',compare,'state.scope.every((value, i) => i === 1 || value === response.scope[i])'],
  ['M03 ignore stream',compare,'state.scope.every((value, i) => i === 2 || value === response.scope[i])'],
  ['M04 ignore consent epoch',compare,'state.scope.every((value, i) => i === 3 || value === response.scope[i])'],
  ['M05 ignore local issuance','localRequestGeneration === state.latestRequestGeneration','true'],
  ['M06 trust echoed local token','localRequestGeneration === state.latestRequestGeneration',
    '(response.localRequestGeneration ?? localRequestGeneration) === state.latestRequestGeneration'],
  ['M07 ignore installed floor','response.postGeneration >= state.installedServerGeneration','true'],
  ['M08 reject equal server generation','response.postGeneration >= state.installedServerGeneration',
    'response.postGeneration > state.installedServerGeneration'],
  ['M09 ignore commit status',"response.status === 'COMMITTED_CURRENT'",'true'],
  ['M10 truthy cursor instead of string',"typeof response.cursor === 'string' && response.cursor.length > 0",'Boolean(response.cursor)'],
  ['M11 allow empty cursor','response.cursor.length > 0','response.cursor.length >= 0'],
  ['M12 coerce generation numbers','Number.isSafeInteger(v) && v >= min','Number.isSafeInteger(Number(v)) && Number(v) >= min'],
  ['M13 accept unsafe integers','Number.isSafeInteger(v)','Number.isInteger(v)'],
  ['M14 zero allowed for every generation','v >= min','v >= 0'],
  ['M15 scope may have trailing fields','v.length === 4','v.length >= 4'],
  ['M16 allow empty scope members','v[i].length > 0','v[i].length >= 0'],
  ['M17 fold scope case',compare,'state.scope.every((value, i) => value.toLowerCase() === response.scope[i].toLowerCase())'],
  ['M18 normalize scope Unicode',compare,"state.scope.every((value, i) => value.normalize('NFC') === response.scope[i].normalize('NFC'))"],
  ['M19 trim scope strings',compare,'state.scope.every((value, i) => value.trim() === response.scope[i].trim())'],
  ['M20 reject response diagnostics',"return response.status === 'COMMITTED_CURRENT'", 
    "return Object.keys(response).length === 4 && response.status === 'COMMITTED_CURRENT'"],
  ['M21 mutate state',"return response.status === 'COMMITTED_CURRENT'",
    "state.touched = true;\n  return response.status === 'COMMITTED_CURRENT'"],
  ['M22 confuse server and local counters','response.postGeneration >= state.installedServerGeneration',
    'response.postGeneration >= state.latestRequestGeneration'],
  ['M23 return cursor rather than boolean','response.postGeneration >= state.installedServerGeneration;',
    'response.postGeneration >= state.installedServerGeneration && response.cursor;'],
  ['M24 allow future local token','localRequestGeneration === state.latestRequestGeneration',
    'localRequestGeneration >= state.latestRequestGeneration'],
];

console.log(`REFERENCE public=${run(shouldInstallReset)}, hidden=${runHidden(shouldInstallReset)}`);
let killed=0;
for (const [name,old,replacement] of mutants) {
  assert.equal(source.split(old).length-1,1,name+': edit must have exactly one site');
  const mutated=source.replace(old,replacement);
  // Syntax/import failures are not credited as kills.
  const {shouldInstallReset:fn}=await import('data:text/javascript;base64,'+Buffer.from(mutated).toString('base64'));
  assert.equal(typeof fn,'function',name+': callable mutant required');
  let witness;
  for (const test of cases) {
    try { run(fn,[test]); } catch (error) {
      witness={case:test.name,reason:error.code||error.name}; break;
    }
  }
  assert.ok(witness,name+': SURVIVED public acceptance kit');
  killed++;
  console.log(`KILLED ${name} | ${witness.case} | ${witness.reason}`);
}
assert.ok(mutants.length>=10);
console.log(`PASS mutation: ${killed}/${mutants.length} independent mutants killed by public cases; 0 survivors`);
```

