solution.mjs — 1,029 bytes; SHA-256 6a97d0ad7ec907298e2936f32c0a68d529da351e78672db43d775b395f9c0f64
```javascript
export function shouldInstallReset(state, response, localRequestGeneration) {
  const object = v => v !== null && typeof v === 'object' && !Array.isArray(v);
  const scope = v => Array.isArray(v) && v.length === 4 &&
    [0, 1, 2, 3].every(i => typeof v[i] === 'string' && v[i].length > 0);
  const generation = (v, min) => Number.isSafeInteger(v) && v >= min;
  if (!object(state) || !object(response)) return false;
  if (!scope(state.scope) || !scope(response.scope)) return false;
  if (!generation(state.latestRequestGeneration, 1) ||
      !generation(localRequestGeneration, 1) ||
      !generation(state.installedServerGeneration, 0) ||
      !generation(response.postGeneration, 1)) return false;
  return response.status === 'COMMITTED_CURRENT' &&
    typeof response.cursor === 'string' && response.cursor.length > 0 &&
    state.scope.every((value, i) => value === response.scope[i]) &&
    localRequestGeneration === state.latestRequestGeneration &&
    response.postGeneration >= state.installedServerGeneration;
}
```

