```javascript
import assert from 'node:assert/strict';
import { pathToFileURL } from 'node:url';
import { resolve } from 'node:path';
import { run } from './public_test.mjs';

const scope = ['acct', 'conv', 'stream', 'epoch'];
const S = { scope, latestRequestGeneration: 2, installedServerGeneration: 4 };
const R = { scope, status: 'COMMITTED_CURRENT', postGeneration: 4, cursor: 'c' };
export const hiddenCases = [];
const add = (name, expected, state = S, response = R, local = 2) =>
  hiddenCases.push({ name, expected, args: [state, response, local] });

// Each row declares validity explicitly; this oracle does not call the reference.
const positive = [[1,true],[2,true],[4,true],[Number.MAX_SAFE_INTEGER,true],
  [0,false],[-1,false],[2.5,false],['2',false],[Number.MAX_SAFE_INTEGER+1,false]];
const installed = [[0,true],[1,true],[4,true],[Number.MAX_SAFE_INTEGER,true],
  [-1,false],[2.5,false],['4',false],[null,false],[Number.MAX_SAFE_INTEGER+1,false]];
for (const [latest,lv] of positive) for (const [local,qv] of positive)
  for (const [old,ov] of installed) for (const [post,pv] of positive) {
    const expected = lv && qv && ov && pv && latest === local && post >= old;
    add(`generation grid ${hiddenCases.length}`, expected,
      {...S,latestRequestGeneration:latest,installedServerGeneration:old},
      {...R,postGeneration:post}, local);
  }
for (const key of Object.keys(S)) {
  const state = {...S}; delete state[key];
  add('missing state.'+key, false, state);
}
for (const key of Object.keys(R)) {
  const response = {...R}; delete response[key];
  add('missing response.'+key, false, S, response);
}
hiddenCases.push({name:'missing third argument',expected:false,args:[S,R]});
for (let i=0;i<4;i++) for (const bad of [null,0,false,[],{}]) {
  const broken = [...scope]; broken[i] = bad;
  add(`state component ${i}: ${JSON.stringify(bad)}`,false,{...S,scope:broken});
  add(`response component ${i}: ${JSON.stringify(bad)}`,false,S,{...R,scope:broken});
}
for (let length=0;length<=7;length++) {
  const shape = Array.from({length},(_,i)=>scope[i] ?? 'extra');
  add('state scope length '+length,length===4,{...S,scope:shape});
  add('response scope length '+length,length===4,S,{...R,scope:shape});
}
for (const cursor of ['0','\u0000','\t\n','\ud83d\udd11'])
  add('nonempty primitive cursor '+JSON.stringify(cursor),true,S,{...R,cursor});
for (const value of ['\u0000','\t','\u00e9','e\u0301','\ud83d\udd11']) {
  const exact = [value,value,value,value];
  add('identical unusual scope '+JSON.stringify(value),true,{...S,scope:exact},{...R,scope:exact});
}
add('installed negative zero is allowed',true,{...S,installedServerGeneration:-0});
add('server and local counters are unrelated',true,
  {...S,latestRequestGeneration:900,installedServerGeneration:0},{...R,postGeneration:1},900);
add('local current cannot rescue old server',false,
  {...S,latestRequestGeneration:1,installedServerGeneration:900},{...R,postGeneration:899},1);
add('diagnostic status cannot veto valid envelope',true,
  {...S,response:{status:'DENIED'},cursor:null},
  {...R,error:'DENIED',current:false,committed:false,authorized:false,
    latestRequestGeneration:999,installedServerGeneration:999});
add('diagnostic cursor cannot replace missing cursor',false,S,
  {...R,cursor:'',diagnostics:{cursor:'valid-looking',status:'COMMITTED_CURRENT'}});

export function runHidden(fn) {
  const count = run(fn, hiddenCases);
  // A valid immutable graph must also be accepted, without writes being attempted.
  const freeze = value => {
    if (value && typeof value === 'object') {
      Object.values(value).forEach(freeze); Object.freeze(value);
    }
    return value;
  };
  const frozen = freeze(structuredClone([S,R,2]));
  assert.equal(fn(...frozen), true, 'deep-frozen valid inputs');
  return count + 1;
}
if (process.argv[1] && import.meta.url===pathToFileURL(resolve(process.argv[1])).href) {
  const {shouldInstallReset}=await import(pathToFileURL(resolve(process.argv[2]||'solution.mjs')));
  console.log(`PASS hidden: ${runHidden(shouldInstallReset)} cases`);
}
```

