```javascript
import assert from 'node:assert/strict';
import { pathToFileURL } from 'node:url';
import { resolve } from 'node:path';

const S = {scope:['account-A','conversation-A','stream-A','epoch-A'],
  latestRequestGeneration:2, installedServerGeneration:4};
const R = {status:'COMMITTED_CURRENT', scope:S.scope,
  postGeneration:4, cursor:'cursor-A'};
export const cases = [];
const add = (name, expected, s={}, r={}, q=2) =>
  cases.push({name, expected, args:[{...S,...s},{...R,...r},q]});
add('equal-generation replay',true);
add('new server generation',true,{}, {postGeneration:5});
add('initial install',true,{installedServerGeneration:0},{postGeneration:1});
add('server regression',false,{}, {postGeneration:3});
add('q1 after q2 before install',false,{installedServerGeneration:0},
  {postGeneration:100,localRequestGeneration:2,requestGeneration:2},1);
add('future local request',false,{}, {},3);
add('response cannot supply local token',false,{}, {localRequestGeneration:2},null);
add('diagnostic fields ignored',true,{debug:{current:false}},
  {debug:{denied:true},localRequestGeneration:999,requestGeneration:999});
add('diagnostics cannot override status',false,{}, {status:'DENIED',debug:{current:true}});
for (const status of ['DENIED','PENDING','committed_current','',null,1,true])
  add('bad status '+String(status),false,{}, {status});
for (const cursor of ['',null,1,true,[],{}])
  add('bad cursor '+JSON.stringify(cursor),false,{}, {cursor});
add('whitespace is a nonempty cursor',true,{}, {cursor:' '});
for (let i=0;i<4;i++) {
  const scope=[...S.scope]; scope[i]+='x';
  add('scope mismatch '+i,false,{}, {scope});
  const empty=[...S.scope]; empty[i]='';
  add('empty scope member '+i,false,{scope:empty},{scope:empty});
}
for (const scope of [null,{},'scope',[],S.scope.slice(0,3),[...S.scope,'extra']]) {
  add('bad state scope '+JSON.stringify(scope),false,{scope});
  add('bad response scope '+JSON.stringify(scope),false,{}, {scope});
}
add('case is exact',false,{scope:['A','c','s','e']},{scope:['a','c','s','e']});
add('Unicode is exact',false,{scope:['\u00e9','c','s','e']},
  {scope:['e\u0301','c','s','e']});
add('scope whitespace is significant',false,{scope:[' a','c','s','e']},
  {scope:['a','c','s','e']});
add('nonempty whitespace scope allowed',true,{scope:[' ','c','s','e']},
  {scope:[' ','c','s','e']});
for (const v of [null,true,'2',[],{},-1,1.5,Number.MAX_SAFE_INTEGER+1]) {
  add('invalid latest '+JSON.stringify(v),false,{latestRequestGeneration:v});
  add('invalid local '+JSON.stringify(v),false,{}, {},v);
  add('invalid installed '+JSON.stringify(v),false,{installedServerGeneration:v});
  add('invalid post '+JSON.stringify(v),false,{}, {postGeneration:v});
}
add('zero latest/local',false,{latestRequestGeneration:0},{},0);
add('zero post',false,{installedServerGeneration:0},{postGeneration:0});
add('safe integer upper boundary',true,
  {latestRequestGeneration:Number.MAX_SAFE_INTEGER,installedServerGeneration:Number.MAX_SAFE_INTEGER},
  {postGeneration:Number.MAX_SAFE_INTEGER},Number.MAX_SAFE_INTEGER);
for (const v of [null,[],true,1,'state']) {
  cases.push({name:'nonobject state '+JSON.stringify(v),expected:false,args:[v,R,2]});
  cases.push({name:'nonobject response '+JSON.stringify(v),expected:false,args:[S,v,2]});
}

export function run(fn, suite=cases) {
  assert.equal(typeof fn,'function');
  for (const {name,expected,args} of suite) {
    const input=structuredClone(args), before=structuredClone(input);
    assert.equal(fn(...input),expected,name);
    assert.deepEqual(input,before,name+': inputs mutated');
  }
  return suite.length;
}
